const e=[{id:"sv-2-641",phase:2,topic:"2.1.3",qtype:"concept",difficulty:1,stem:"What is the main purpose of an X-Y diagram in the Measure phase?",options:["To verify statistically which inputs cause a change in the output","To rank failure modes by severity, occurrence and detection","To rank counted defect categories by how often they occur","To prioritise the potential inputs by their relative impact on several outputs"],answer:3,hint:"X-Y matrix = team-based prioritisation of potential X's against multiple Y's.",steps:[{title:"Key idea",body:"The book calls the X-Y matrix a tool to identify potential X's and assess their **relative impact on multiple Y's**."},{title:"Eliminate look-alikes",body:"Proof belongs to Analyze tests, S-O-D ranking to the FMEA, counted categories to a Pareto chart."}],final:"Prioritises potential X's against several Y's → answer **D**",whyWrong:["Incorrect — statistical verification of X's is done with hypothesis tests in Analyze.","Incorrect — ranking failure modes by S, O and D is the FMEA.","Incorrect — ranking counted defect categories is a Pareto chart.",""],bookRef:"Book p. 118"},{id:"sv-2-642",phase:2,topic:"2.1.3",qtype:"concept",difficulty:1,stem:"In the body of an X-Y matrix, what does a rating of **9** in a cell indicate?",options:["The output in that column is the most important to the customer","The team believes that input has a strong effect on that output","The input holds ninth place in the final ranking","The input caused nine defects during the baseline period"],answer:1,hint:"Cell ratings use 0 / 1 / 3 / 9 for the strength of the X–Y link.",steps:[{title:"Key idea",body:"Each cell rates how strongly the X affects that Y: 9 strong, 3 moderate, 1 weak, 0 none."},{title:"Apply",body:"A 9 is the strongest believed relationship; it says nothing about the Y's importance or about counts."}],final:"9 = strong relationship → answer **B**",whyWrong:["Incorrect — customer importance is the output weight (1–10) above the column, not a cell rating.","","Incorrect — the ranking is the weighted row total, not a cell value.","Incorrect — the matrix holds opinion ratings, not counts of defects."],bookRef:"Book pp. 120–121"},{id:"sv-2-643",phase:2,topic:"2.1.3",qtype:"concept",difficulty:1,stem:"In an X-Y matrix, what does the weight written above each output (Y) column represent?",options:["The strength of the link between an input and that output","The number of inputs believed to affect that output","The current baseline performance of that output","The relative importance of that output to the customer and business"],answer:3,hint:"Weights belong to the Y's (1–10); ratings belong to the X–Y cells.",steps:[{title:"Key idea",body:"Each Y is weighted 1–10, with 10 the most important output."},{title:"Eliminate",body:"Link strength is the cell rating; counts and baselines are not part of the weight."}],final:"Weight = importance of the Y → answer **D**",whyWrong:["Incorrect — the strength of an X–Y link is the cell rating (0/1/3/9).","Incorrect — the weight is not a count of inputs; it ranks the Y's by importance.","Incorrect — baseline performance is measured in Measure, not entered as a weight.",""],bookRef:"Book pp. 120–121"},{id:"sv-2-644",phase:2,topic:"2.1.3",qtype:"concept",difficulty:2,stem:"Which are the three primary sources of potential X's that the book lists before an X-Y matrix is built?",options:["Control charts, capability studies and Gage R&R studies","Process mapping, fishbone analysis and basic data analysis","Project charter, SIPOC and stakeholder analysis","Pilot results, designed experiments and regression models"],answer:1,hint:"Recall the book's 'three primary sources' of X's.",steps:[{title:"Key idea",body:"The book lists process mapping, fishbone analysis and basic graphical/statistical data analysis."},{title:"Apply",body:"The X-Y matrix then prioritises the long list these sources produce."}],final:"Process map + fishbone + basic data analysis → answer **B**",whyWrong:["Incorrect — these are Measure/Control analysis tools for stability, capability and measurement error.","","Incorrect — these Define tools set scope and stakeholders, not the detailed list of X's.","Incorrect — these are Improve/Analyze tools used after the X's are prioritised."],bookRef:"Book p. 118"},{id:"sv-2-645",phase:2,topic:"2.1.3",qtype:"concept",difficulty:2,stem:"From the fishbone, which type of input does the book recommend placing in the X-Y matrix?",options:["Controllable inputs","Noise inputs","Output measures","Procedural inputs"],answer:0,hint:"Which X's can the team actually adjust?",steps:[{title:"Key idea",body:"The book puts the **controllable** X's into the X-Y matrix to find the vital few."},{title:"Eliminate",body:"Procedural and noise X's are carried into the FMEA; outputs are Y's."}],final:"Controllable X's go into the X-Y matrix → answer **A**",whyWrong:["","Incorrect — noise inputs go to the FMEA, where they tend to raise risk.","Incorrect — outputs are the Y's across the top, not inputs from the fishbone.","Incorrect — procedural inputs go to the FMEA, not the X-Y matrix."],bookRef:"Book p. 119"},{id:"sv-2-646",phase:2,topic:"2.1.3",qtype:"concept",difficulty:3,stem:"How does an X-Y matrix differ from a Pareto chart of defect types?",options:["It ranks counted defect categories from most to least frequent","It ranks failure modes by the product of three 1–10 ratings","It ranks inputs by believed impact on weighted outputs, not by counted occurrences","It ranks outputs by customer importance without considering inputs"],answer:2,hint:"Opinion-based scores of X's versus counted data by category.",steps:[{title:"Key idea",body:"The X-Y matrix totals team ratings × Y weights for each X; a Pareto chart sorts counted data."},{title:"Eliminate",body:"RPN belongs to the FMEA; ranking only the Y's misses the purpose of the matrix."}],final:"Believed impact on weighted Y's vs counted occurrences → answer **C**",whyWrong:["Incorrect — ranking counted categories by frequency is exactly what a Pareto chart does.","Incorrect — the product of three ratings is the FMEA's RPN.","","Incorrect — weights rank the Y's, but the matrix exists to rank the X's."],bookRef:"Book pp. 118–122"},{id:"sv-2-647",phase:2,topic:"2.1.3",qtype:"concept",difficulty:2,stem:"How are the X-Y matrix results applied when planning data collection?",options:["By collecting data on every listed input equally to avoid bias","By collecting data first on the outputs with the highest weights","By collecting data first on inputs rated 0 to confirm they have no effect","By collecting data first on the inputs with the highest weighted totals"],answer:3,hint:"The book puts graphing and data work on 'the top X's from the X-Y diagram'.",steps:[{title:"Key idea",body:"The matrix narrows the list so data collection focuses on the top-ranked X's."},{title:"Apply",body:"Only the first option uses the X totals to direct the data effort."}],final:"Collect data on the top-ranked X's first → answer **D**",whyWrong:["Incorrect — the matrix exists precisely so the team does not measure every input equally.","Incorrect — weights rank the Y's; data collection targets the top-ranked X's.","Incorrect — inputs rated 0 are the obvious low-impact X's to drop, not to study first.",""],bookRef:"Book p. 159"},{id:"sv-2-648",phase:2,topic:"2.1.3",qtype:"concept",difficulty:1,stem:"The X-Y matrix helps the team separate which two groups?",options:["Value-added steps from non-value-added steps","The vital few X's from the trivial many","Common-cause variation from special-cause variation","Defective units from defect-free units"],answer:1,hint:"Think Pareto principle applied to the inputs.",steps:[{title:"Key idea",body:"The book's goal for the matrix is to separate the vital few X's from the trivial many."},{title:"Eliminate",body:"VA/NVA, common/special cause and inspection belong to other tools."}],final:"Vital few X's vs trivial many → answer **B**",whyWrong:["Incorrect — separating VA from NVA steps is value stream mapping.","","Incorrect — common versus special cause is read from a control chart.","Incorrect — sorting defective units is inspection, not input prioritisation."],bookRef:"Book p. 119"},{id:"sv-2-649",phase:2,topic:"2.1.3",qtype:"concept",difficulty:1,stem:"Which outputs should be listed across the top of an X-Y matrix?",options:["Only the inputs the team can directly control","The process steps taken from the level 1 process map","The project's primary metric and its secondary, customer-focused metrics","The failure modes recorded in the defect history"],answer:2,hint:"Y's across the top, X's down the side.",steps:[{title:"Key idea",body:"The book lists the primary metric and secondary metrics as the Y's, including all customer-focused Y's."},{title:"Eliminate",body:"Inputs, steps and failure modes are other parts of the Measure toolkit."}],final:"Primary + secondary metrics → answer **C**",whyWrong:["Incorrect — inputs are the X's listed down the side, not the Y's across the top.","Incorrect — process steps head the FMEA rows, not the X-Y matrix columns.","","Incorrect — failure modes belong in the FMEA, not as Y columns."],bookRef:"Book pp. 118, 120"},{id:"sv-2-650",phase:2,topic:"2.1.3",qtype:"concept",difficulty:2,stem:"How is the ranking for each input in an X-Y matrix obtained?",options:["By adding the ratings across the row without using the weights","By multiplying all of the ratings in the row together","By averaging the weights of the outputs the input affects","By multiplying each rating by its output's weight and adding across the row"],answer:3,hint:"Ranking = Σ (rating × weight) across the row.",steps:[{title:"Key idea",body:"Each cell rating is multiplied by the weight of its Y; the products are summed for the X."},{title:"Eliminate",body:"Raw sums, products and averages each drop part of the rule."}],final:"Σ rating × weight → answer **D**",whyWrong:["Incorrect — unweighted sums ignore which outputs matter most to the customer.","Incorrect — multiplying ratings together resembles the FMEA's RPN, not the X-Y ranking.","Incorrect — averaging weights ignores how strongly the input affects each output.",""],bookRef:"Book pp. 120–121"},{id:"sv-2-651",phase:2,topic:"2.1.3",qtype:"concept",difficulty:2,stem:"What is the main limitation of the X-Y matrix?",options:["It can only compare inputs against a single output at a time","Its ratings are opinions, so the top X's must still be verified with data","It cannot use inputs identified on the process map","It can only be used once the process is in statistical control"],answer:1,hint:"'This is not real data, this is organised brainstorming.'",steps:[{title:"Key idea",body:"The book warns the matrix is not real data; critical-looking X's may prove unimportant."},{title:"Apply",body:"Hence the Analyze phase tests the top X's with data."}],final:"Opinion-based → verify in Analyze → answer **B**",whyWrong:["Incorrect — the matrix is designed for multiple Y's at once.","","Incorrect — the process map is one of the three primary sources of X's.","Incorrect — stability is not a prerequisite; the matrix uses team knowledge."],bookRef:"Book p. 118"},{id:"sv-2-652",phase:2,topic:"2.1.3",qtype:"concept",difficulty:1,stem:"In which DMAIC phase are the top X's from the X-Y matrix normally tested with data?",options:["Analyze","Control","Define","Improve"],answer:0,hint:"Measure prioritises X's; the next phase proves them.",steps:[{title:"Key idea",body:"The X-Y matrix is built in Measure from opinion; Analyze tests the top X's with data."},{title:"Eliminate",body:"Define, Improve and Control come before or after that verification."}],final:"Top X's are tested in Analyze → answer **A**",whyWrong:["","Incorrect — Control sustains gains; it does not test candidate causes.","Incorrect — Define sets the problem and scope before X's are listed.","Incorrect — Improve acts on X's that Analyze has already verified."],bookRef:"Book p. 118"},{id:"sv-2-653",phase:2,topic:"2.1.3",qtype:"concept",difficulty:2,stem:"What does the **rank %** printed beside each input in an X-Y matrix summary show?",options:["The probability that the input causes the defect","The percentage of defects in the data that the input caused","Its weighted total as a share of the total of all inputs' rankings","The share of team members who rated the input a 9"],answer:2,hint:"Rank % = ranking ÷ total of all rankings.",steps:[{title:"Key idea",body:"The template divides each X's ranking by the sum of all rankings."},{title:"Eliminate",body:"It is not a probability, a defect share or a vote count."}],final:"Share of the total ranking → answer **C**",whyWrong:["Incorrect — the matrix gives no probabilities; it is organised brainstorming.","Incorrect — no defect data are counted; the totals come from ratings × weights.","","Incorrect — the team agrees one rating per cell; no vote share is shown."],bookRef:"Book p. 122"},{id:"sv-2-654",phase:2,topic:"2.1.3",qtype:"concept",difficulty:3,stem:"When reviewing a completed X-Y matrix as a Measure deliverable, which question does the book's checklist ask?",options:["What p-value each input achieved","Which control chart was selected for each input","How many failure modes exceeded an RPN threshold","Who participated in building it"],answer:3,hint:"An opinion tool is only as good as the people who scored it.",steps:[{title:"Key idea",body:"The Measure checklist asks who participated; a matrix filled in by one person is a known roadblock."},{title:"Eliminate",body:"p-values, control charts and RPNs belong to other tools and phases."}],final:"Checklist: who participated → answer **D**",whyWrong:["Incorrect — p-values come from Analyze hypothesis tests, not the opinion-based matrix.","Incorrect — control chart selection belongs to the Control phase.","Incorrect — RPN thresholds belong to the FMEA.",""],bookRef:"Book pp. 229–231"},{id:"sv-2-655",phase:2,topic:"2.1.3",qtype:"concept",difficulty:2,stem:"The book calls the X-Y matrix a 'fairly unbiased' way to focus the team even though it is opinion-based. Why?",options:["It replaces opinions with measured data for every rating","It forces a structured team scoring of every input against every weighted output","It is scored by an independent auditor outside the team","It hides the output weights from the people doing the scoring"],answer:1,hint:"Structure + whole team = less bias, even without data.",steps:[{title:"Key idea",body:"Every X is rated against every Y by the team, using agreed weights, so no single voice decides."},{title:"Eliminate",body:"No measured data, no outside auditor and no hidden weights are involved."}],final:"Structured, team-wide scoring → answer **B**",whyWrong:["Incorrect — the book stresses the ratings are not real data.","","Incorrect — the team itself scores the matrix using its collective knowledge.","Incorrect — weights are agreed openly by the team before scoring."],bookRef:"Book p. 118"},{id:"sv-2-656",phase:2,topic:"2.1.3",qtype:"concept",difficulty:2,stem:"How does the X-Y matrix relate to the Y = f(X) idea?",options:["It calculates the regression equation that links Y to the X's","It measures how the Y varies over time on a control chart","It lists candidate X's and estimates how strongly each drives the Y's","It writes the operational definition for each Y"],answer:2,hint:"Y = f(X): which X's are believed to drive the Y's?",steps:[{title:"Key idea",body:"The matrix puts the Y's across the top and candidate X's down the side, scoring each link."},{title:"Eliminate",body:"Equations, time plots and definitions come from other tools."}],final:"Estimates believed X → Y links → answer **C**",whyWrong:["Incorrect — regression fits an equation from data in Analyze.","Incorrect — monitoring Y over time is a control chart's job.","","Incorrect — operational definitions belong to the data collection plan."],bookRef:"Book p. 118"},{id:"sv-2-657",phase:2,topic:"2.1.3",qtype:"concept",difficulty:3,stem:"In an X-Y matrix, why should the team agree what a 9, 3, 1 and 0 mean before scoring?",options:["So the ratings can later be converted into measured correlation values","So the output weights can be calculated from the ratings","So the matrix can be completed without the cross-functional team","So ratings stay consistent and one enthusiastic expert does not inflate a row"],answer:3,hint:"Operational meaning for each rating = consistent judgement.",steps:[{title:"Key idea",body:"A shared meaning for strong, moderate, weak and none keeps the team's judgement consistent."},{title:"Eliminate",body:"It does not create data, set weights or remove the need for the team."}],final:"Agreed meanings keep scoring consistent → answer **D**",whyWrong:["Incorrect — ratings remain opinions; they never become measured correlations.","Incorrect — weights are set separately on a 1–10 scale for the Y's.","Incorrect — the matrix depends on the team's collective knowledge.",""],bookRef:"Book pp. 120–121"},{id:"sv-2-658",phase:2,topic:"2.1.3",qtype:"concept",difficulty:2,stem:"A sponsor describes the X-Y matrix as hard evidence about the process. Which statement about the X-Y matrix is CORRECT?",options:["Its ratings reflect the team's collective opinion rather than measured data","It proves which inputs cause the change in the output","It is built once in Define and then archived","It ranks the outputs, not the inputs, by importance"],answer:0,hint:"'Tribal knowledge' — organised brainstorming.",steps:[{title:"Key idea",body:"The book bases the matrix on the team's collective opinions; it is not real data."},{title:"Eliminate",body:"It does not prove causation, is not a one-off, and ranks X's."}],final:"Team opinion, not data → answer **A**",whyWrong:["","Incorrect — proof needs Analyze-phase data; the matrix only prioritises.","Incorrect — it is built in Measure and is never completed; it is updated when parameters change.","Incorrect — weights rank the Y's, but the matrix's job is to rank the X's."],bookRef:"Book p. 118"},{id:"sv-2-659",phase:2,topic:"2.1.3",qtype:"concept",difficulty:2,stem:"Which statement about the scales used in an X-Y matrix is CORRECT?",options:["Outputs are weighted 0, 1, 3 or 9 and relationships are rated 1 to 10","Outputs are weighted 1 to 10 and relationships are rated 0, 1, 3 or 9","Outputs and relationships are both rated on a 1 to 10 scale","Outputs are weighted 1 to 5 and relationships are rated 1 to 3"],answer:1,hint:"Two scales: one for Y importance, one for X–Y link strength.",steps:[{title:"Key idea",body:"Weights: 1–10 for each Y. Ratings: 0, 1, 3, 9 for each X–Y cell."},{title:"Trap",body:"The swapped version is the most common mix-up."}],final:"Weights 1–10, ratings 0/1/3/9 → answer **B**",whyWrong:["Incorrect — this swaps the two scales; weights are 1–10 and ratings are 0/1/3/9.","","Incorrect — the book avoids a 1–10 rating scale for relationships to stop 'is it a 6 or a 7?' debates.","Incorrect — neither scale is used in the book's template."],trap:"Do not confuse weights (Y's) with ratings (X–Y cells).",bookRef:"Book pp. 120–121"},{id:"sv-2-660",phase:2,topic:"2.1.3",qtype:"concept",difficulty:1,stem:"Which statement about the X-Y matrix and the FMEA is CORRECT?",options:["Both tools rank the inputs using the same 0, 1, 3 and 9 ratings","The FMEA must be completed before the X-Y matrix can be started","The X-Y matrix ranks inputs by believed impact; the FMEA ranks failure risks by S, O and D","The X-Y matrix replaces the FMEA when the project is short of time"],answer:2,hint:"Two Measure tools with different questions: which X matters vs how it could fail.",steps:[{title:"Key idea",body:"The X-Y matrix prioritises X's against weighted Y's; the FMEA rates severity, occurrence and detection of failures."},{title:"Eliminate",body:"Different scales, X-Y comes first, and neither replaces the other."}],final:"Different tools, different rankings → answer **C**",whyWrong:["Incorrect — only the X-Y matrix uses 0/1/3/9; the FMEA uses three 1–10 ratings.","Incorrect — the X-Y matrix's ranked X's feed the FMEA, so it comes first.","","Incorrect — they answer different questions, so one cannot replace the other."],bookRef:"Book pp. 118, 123"},{id:"sv-2-661",phase:2,topic:"2.1.3",qtype:"concept",difficulty:2,stem:"Which statement about the inputs listed in an X-Y matrix is CORRECT?",options:["Every bone of the fishbone must appear as a separate row","Only inputs that already have historical data may be listed","Inputs must be listed in order of their expected ranking","Not every fishbone cause needs its own row; common sense is applied"],answer:3,hint:"Use judgement when moving X's from the fishbone into the matrix.",steps:[{title:"Key idea",body:"The book: put controllable X's in, and use common sense — not every fishbone item needs a row."},{title:"Eliminate",body:"No data requirement, and sorting happens only after the totals are calculated."}],final:"Common sense on which X's get a row → answer **D**",whyWrong:["Incorrect — the book says to use common sense; not every fishbone item deserves a row.","Incorrect — inputs without data are exactly what the opinion-based matrix handles.","Incorrect — the ranking is calculated after scoring, then the rows are sorted.",""],bookRef:"Book p. 119"},{id:"sv-2-662",phase:2,topic:"2.1.3",qtype:"concept",difficulty:3,stem:"Which statement about scoring an X-Y matrix is CORRECT?",options:["Rating one output column at a time across all inputs keeps judgements consistent","Each input row should be rated by a different team member working alone","Ratings should be adjusted after the totals are seen so the expected input ranks first","Ratings should be taken from measured correlation coefficients"],answer:0,hint:"Consistency comes from comparing all X's against one Y at a time.",steps:[{title:"Key idea",body:"Scoring down one Y column at a time lets the team compare all X's on the same output."},{title:"Eliminate",body:"Solo scoring, reverse-engineering totals and 'measured' ratings all break the tool."}],final:"Score one Y column at a time → answer **A**",whyWrong:["","Incorrect — splitting rows among individuals loses the collective team judgement.","Incorrect — adjusting ratings to reach a desired ranking biases the matrix.","Incorrect — the ratings are opinions; correlation comes later from data."],bookRef:"Book pp. 120–121"},{id:"sv-2-663",phase:2,topic:"2.1.3",qtype:"concept",difficulty:2,stem:"Which statement about the totals in an X-Y matrix is CORRECT?",options:["A higher total proves the input explains more of the variation in the output","A higher total means the team believes the input has more influence on the weighted outputs","A total of zero means the input must be measured before anything else","The totals are only valid if they add up to exactly 100"],answer:1,hint:"Totals reflect believed influence, not proven influence.",steps:[{title:"Key idea",body:"Each total is Σ rating × weight — the team's belief about influence on the important Y's."},{title:"Eliminate",body:"No proof of variation, zero means low impact, and totals need not sum to 100."}],final:"Higher total = more believed influence → answer **B**",whyWrong:["Incorrect — explained variation is measured with data in Analyze, not proven by opinion totals.","","Incorrect — a zero total marks an obvious low-impact X to drop, not a priority.","Incorrect — totals are weighted sums; rank % (not the totals) adds to 100%."],bookRef:"Book pp. 120–122"},{id:"sv-2-664",phase:2,topic:"2.1.3",qtype:"statements",difficulty:2,stem:`Which statements about the X-Y matrix are CORRECT?

1. It is created for every project.
2. It is based on the team's collective opinions.
3. It proves which inputs cause the defect.
4. It is completed once and then archived.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"Book: created for every project, team opinion, never completed.",steps:[{title:"Check each",body:"1 true (every project). 2 true (tribal knowledge). 3 false (no proof). 4 false (living)."},{title:"Match",body:"True pair is 1 and 2."}],final:"Statements 1 and 2 → answer **A**",whyWrong:["","Incorrect — statement 3 is false: the matrix prioritises but does not prove causation.","Incorrect — both are false: no proof of causation, and the matrix is never completed.","Incorrect — statement 4 is false: the matrix is updated whenever a parameter changes."],bookRef:"Book p. 118"},{id:"sv-2-665",phase:2,topic:"2.1.3",qtype:"statements",difficulty:2,stem:`Which inputs from the fishbone does the book say should be carried into the FMEA rather than the X-Y matrix?

1. Controllable inputs.
2. Procedural inputs.
3. Noise inputs.
4. Output metrics.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"Controllable → X-Y matrix; procedural and noise → FMEA.",steps:[{title:"Key idea",body:"The book puts controllable X's in the X-Y matrix and procedural and noise X's in the FMEA."},{title:"Match",body:"Procedural (2) and noise (3)."}],final:"Statements 2 and 3 → answer **B**",whyWrong:["Incorrect — controllable inputs (1) go into the X-Y matrix, not the FMEA.","","Incorrect — output metrics (4) are Y's, so they are neither X-Y inputs nor FMEA causes.","Incorrect — controllable inputs go into the X-Y matrix and output metrics are Y's."],bookRef:"Book p. 119"},{id:"sv-2-666",phase:2,topic:"2.1.3",qtype:"statements",difficulty:3,stem:`Which statements about using the results of an X-Y matrix are CORRECT?

1. The top-ranked inputs are proven root causes.
2. Inputs with the highest totals can go straight to Improve.
3. Data collection should focus on the top-ranked inputs.
4. Obvious low-impact inputs can be dropped from further study.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"Prioritise → collect data → verify; drop the obvious low ones.",steps:[{title:"Check each",body:"1 false (not proof). 2 false (Analyze still needed). 3 true. 4 true (book: eliminate obvious low-impact X's)."},{title:"Match",body:"True pair is 3 and 4."}],final:"Statements 3 and 4 → answer **C**",whyWrong:["Incorrect — both are false: top X's are only prioritised and still need Analyze-phase testing.","Incorrect — statement 2 is false: high totals do not skip the Analyze phase.","","Incorrect — statement 1 is false: an opinion ranking is not proof of a root cause."],bookRef:"Book pp. 118, 159"},{id:"sv-2-667",phase:2,topic:"2.1.3",qtype:"statements",difficulty:3,stem:`Which statements about the place of the X-Y matrix in DMAIC are CORRECT?

1. Its ranked inputs feed the potential causes in the FMEA.
2. It is built in Control to monitor the inputs.
3. It replaces the need for a fishbone diagram.
4. Its top inputs are tested with data in Analyze.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:3,hint:"Fishbone/process map → X-Y matrix → FMEA → Analyze tests.",steps:[{title:"Check each",body:"1 true (FMEA built from process map, fishbone and X-Y matrix). 2 false. 3 false. 4 true."},{title:"Match",body:"True pair is 1 and 4."}],final:"Statements 1 and 4 → answer **D**",whyWrong:["Incorrect — statement 2 is false: the matrix is a Measure tool, not a Control monitoring tool.","Incorrect — both are false: it is a Measure tool, and the fishbone is one of its sources.","Incorrect — statement 3 is false: the fishbone supplies the X's that the matrix ranks.",""],bookRef:"Book pp. 118, 136"},{id:"sv-2-668",phase:2,topic:"2.1.3",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

The book warns that the X-Y matrix is not real data; it is organised [?].`,options:["brainstorming","experimentation","measurement","sampling"],answer:0,hint:"Recall the book's warning on p. 118.",steps:[{title:"Key idea",body:'"This is not real data, this is organized brainstorming."'},{title:"Eliminate",body:"Experimentation, measurement and sampling all generate data."}],final:"Organised brainstorming → answer **A**",whyWrong:["","Incorrect — experimentation (DOE) produces real data in Improve.","Incorrect — measurement produces data; the matrix is explicitly not data.","Incorrect — sampling is a data collection method, not the basis of the matrix."],bookRef:"Book p. 118"},{id:"sv-2-669",phase:2,topic:"2.1.3",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

The X-Y matrix is based on the team's collective opinions, which the book calls [?] knowledge.`,options:["expert","statistical","tacit","tribal"],answer:3,hint:"The book's informal term for what the team already knows.",steps:[{title:"Key idea",body:"The book says the matrix is based on the team's collective opinions — 'tribal knowledge'."},{title:"Eliminate",body:"Statistical knowledge needs data; expert and tacit are not the book's word."}],final:"Tribal knowledge → answer **D**",whyWrong:["Incorrect — the matrix draws on the whole team, not a single expert.","Incorrect — statistical knowledge comes from data, which the matrix is not.","Incorrect — plausible in general, but not the book's term.",""],bookRef:"Book p. 118"},{id:"sv-2-670",phase:2,topic:"2.1.3",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

The X-Y matrix is created for every project and is never [?]; it is updated whenever a parameter changes.`,options:["approved","completed","sorted","weighted"],answer:1,hint:"A living document is never ...",steps:[{title:"Key idea",body:"The book: created for every project, **never completed**, updated whenever a parameter changes."},{title:"Eliminate",body:"Sorting and weighting are normal steps; approval is not mentioned."}],final:"Never completed → answer **B**",whyWrong:["Incorrect — approval is not the issue; the matrix is a living document.","","Incorrect — the inputs are sorted by ranking as part of building the matrix.","Incorrect — the outputs are weighted 1–10 as a normal step."],bookRef:"Book p. 118"},{id:"sv-2-671",phase:2,topic:"2.1.3",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

The X-Y diagram is also called the cause and effect [?].`,options:["chart","diagram","matrix","table"],answer:2,hint:"Fishbone = C&E diagram; X-Y = C&E ...",steps:[{title:"Key idea",body:"The X-Y diagram is also known as the X-Y matrix or cause and effect (C&E) matrix."},{title:"Trap",body:"The cause and effect **diagram** is the fishbone."}],final:"Cause and effect matrix → answer **C**",whyWrong:["Incorrect — a 'chart' is not the book's alternative name.","Incorrect — a cause and effect diagram is the fishbone, a different tool.","","Incorrect — 'table' is not the recognised alternative name."],trap:"C&E diagram = fishbone; C&E matrix = X-Y diagram.",bookRef:"Book p. 116"},{id:"sv-2-672",phase:2,topic:"2.1.3",qtype:"not-except",difficulty:1,stem:"Which question can an X-Y matrix NOT answer?",options:["Which inputs should the team study first?","Which inputs look like obvious low-impact candidates?","How much does each input shift the mean of the output?","Which inputs are believed to affect the most important outputs?"],answer:2,hint:"Opinion ratings cannot measure an effect size.",steps:[{title:"Key idea",body:"The matrix prioritises X's from team opinion; it is not real data."},{title:"Apply",body:"The size of an X's effect on the Y must be measured in Analyze."}],final:"Effect size needs data → answer **C**",whyWrong:["Incorrect — choosing what to study first is the matrix's main job.","Incorrect — low totals flag the obvious low-impact X's to drop.","","Incorrect — weighted totals show which X's are believed to drive the key Y's."],bookRef:"Book p. 118"},{id:"sv-2-673",phase:2,topic:"2.1.3",qtype:"not-except",difficulty:3,stem:"Which is NOT a later use of the X-Y matrix results described in the course material?",options:["Supplying potential causes to the FMEA","Choosing the X's for a multi-vari study","Ranking solutions in an improvement selection matrix","Setting the specification limits for each output"],answer:3,hint:"Specification limits come from the customer, not from team ratings.",steps:[{title:"Key idea",body:"The ranked X's feed the FMEA, multi-vari studies and the improvement selection matrix."},{title:"Apply",body:"Specification limits come from customer requirements (VOC/CTQ), not the matrix."}],final:"Spec limits are not set from the X-Y matrix → answer **D**",whyWrong:["Incorrect — this is a real use: the FMEA is built from the process map, fishbone and X-Y matrix.","Incorrect — this is a real use: multi-vari X's can be pulled from the X-Y matrix.","Incorrect — this is a real use: the improvement selection matrix reuses the Y's and their weights.",""],bookRef:"Book pp. 118, 136"},{id:"sv-2-674",phase:2,topic:"2.1.3",qtype:"not-except",difficulty:1,stem:"Which element is NOT part of an X-Y matrix?",options:["Severity rating for each failure effect","Importance weight for each output","List of inputs down the left side","Relationship rating in each cell"],answer:0,hint:"Look for the column that belongs to a different tool.",steps:[{title:"Key idea",body:"The matrix has inputs (rows), outputs with weights (columns) and cell ratings."},{title:"Apply",body:"Severity of a failure effect is an FMEA column."}],final:"Severity belongs to the FMEA → answer **A**",whyWrong:["","Incorrect — output weights (1–10) are a core part of the matrix.","Incorrect — the X's are listed in rows down the left side.","Incorrect — each cell holds a 0/1/3/9 relationship rating."],bookRef:"Book pp. 120–121, 127"},{id:"sv-2-675",phase:2,topic:"2.1.3",qtype:"not-except",difficulty:3,stem:"All of the following are signs of a poorly built X-Y matrix EXCEPT:",options:["Every input rated 3 against every output","Ratings agreed by a cross-functional team after defining each rating","The whole matrix scored by one manager alone","Weights changed so that a favoured input ranks first"],answer:1,hint:"Which option describes good practice?",steps:[{title:"Key idea",body:"A good matrix is scored by the team, with agreed meanings, weights tied to the customer and ratings that discriminate."},{title:"Apply",body:"Only the cross-functional, defined-ratings option is good practice."}],final:"Team scoring with defined ratings is good practice → answer **B**",whyWrong:["Incorrect — this is a sign of poor building: identical ratings cannot separate the vital few.","","Incorrect — this is a known roadblock: one person's guesses replace team knowledge.","Incorrect — this is a sign of bias: weights should reflect customer importance."],bookRef:"Book pp. 229–231"},{id:"sv-2-676",phase:2,topic:"2.1.3",qtype:"scenario",difficulty:2,stem:"To save time, a Black Belt ranks the inputs in an X-Y matrix by adding the raw 0/1/3/9 ratings across each row and ignoring the output weights. What is the main risk of this shortcut?",options:["The ratings become measured data instead of opinions","Inputs rated 0 will be ranked above inputs rated 9","Inputs that affect the most important outputs may be ranked too low","The matrix will rank the outputs instead of the inputs"],answer:2,hint:"Why does the book multiply ratings by Y weights?",steps:[{title:"Key idea",body:"Weights make an X that drives the most important Y rank higher."},{title:"Apply",body:"Without weights, an X linked to a minor Y can outrank one linked to the critical Y."}],final:"Ignoring weights under-ranks X's linked to key Y's → answer **C**",whyWrong:["Incorrect — ratings stay opinions whether or not weights are applied.","Incorrect — a raw sum still places 9s above 0s; the issue is ignoring importance.","","Incorrect — rows are still inputs; only the weighting is lost."],bookRef:"Book pp. 120–121"},{id:"sv-2-677",phase:2,topic:"2.1.3",qtype:"scenario",difficulty:2,stem:"A new eSIM activation process has just gone live and no performance data exist yet. The team wants an organised way to agree which of 15 inputs most affect activation time and activation errors, with errors judged twice as important. Which tool should the Black Belt use?",options:["Control chart","Pareto chart","Regression analysis","X-Y matrix"],answer:3,hint:"No data + several weighted Y's + many X's.",steps:[{title:"Key idea",body:"The X-Y matrix uses team knowledge to rank X's against several weighted Y's."},{title:"Eliminate",body:"Control charts, Pareto charts and regression all need data that do not exist yet."}],final:"X-Y matrix → answer **D**",whyWrong:["Incorrect — a control chart needs process data over time.","Incorrect — a Pareto chart needs counted data by category.","Incorrect — regression needs measured X and Y data.",""],bookRef:"Book p. 118"},{id:"sv-2-678",phase:2,topic:"2.1.3",qtype:"scenario",difficulty:3,stem:"In Analyze, a hypothesis test shows that the input the team rated highest in its X-Y matrix has no significant effect on the primary metric. What does this indicate?",options:["The X-Y matrix was built wrongly and the project must return to Define","The hypothesis test must be wrong because the team rated the input a 9","The input should still be changed in Improve because the team ranked it first","This is expected at times; update the matrix and test the next-ranked inputs"],answer:3,hint:"Book: X's thought critical may turn out unimportant.",steps:[{title:"Key idea",body:"The book warns that X's the team believed critical may prove unimportant at the end of the project."},{title:"Apply",body:"Keep the matrix alive: update it and move on to the next candidates."}],final:"Normal surprise → update and test the next X's → answer **D**",whyWrong:["Incorrect — surprises are normal; they do not mean the whole project must restart.","Incorrect — data outweigh opinion; the matrix is not real data.","Incorrect — Improve acts on verified X's, not on opinion rankings.",""],bookRef:"Book p. 118"},{id:"sv-2-679",phase:2,topic:"2.1.3",qtype:"scenario",difficulty:3,stem:"A team could not agree on its ratings and finally rated every input **3** against every output in its X-Y matrix. What is the main consequence?",options:["The matrix cannot separate the vital few inputs from the trivial many","The matrix now shows that all inputs are proven to matter equally","The output weights will be ignored in the totals","The inputs will need to be moved into the FMEA instead"],answer:0,hint:"A prioritisation tool must discriminate.",steps:[{title:"Key idea",body:"The wide 0/1/3/9 gaps exist to make strong X's stand out."},{title:"Apply",body:"Identical ratings give no discrimination, so no vital few appear."}],final:"No discrimination between inputs → answer **A**",whyWrong:["","Incorrect — equal opinion scores prove nothing; they only hide differences.","Incorrect — weights still multiply the ratings; they simply affect every row alike.","Incorrect — the FMEA takes procedural and noise X's, not unscored controllable ones."],bookRef:"Book pp. 119–121"},{id:"sv-2-680",phase:2,topic:"2.1.3",qtype:"scenario",difficulty:1,stem:"A team has ranked its inputs in an X-Y matrix. For the top six inputs it now wants to identify how each could fail, how serious the effect would be and how well current controls would catch it. Which tool should it use next?",options:["FMEA","Pareto chart","Project charter","SIPOC"],answer:0,hint:"Failure, severity, controls → which tool?",steps:[{title:"Key idea",body:"The FMEA rates severity, occurrence and detection for each failure mode and cause."},{title:"Apply",body:"The book's FMEA exercise is built from the process map, fishbone and X-Y matrix."}],final:"FMEA follows the X-Y matrix → answer **A**",whyWrong:["","Incorrect — a Pareto chart ranks counted categories, not risks of failure.","Incorrect — the charter is a Define document for problem, goal and scope.","Incorrect — SIPOC sets high-level process scope in Define."],bookRef:"Book pp. 123, 136"},{id:"sv-2-681",phase:2,topic:"2.1.3",qtype:"scenario",difficulty:1,stem:"Complaint analysis shows that customers care most about **billing accuracy**, while **internal report timeliness** matters least. Which pair of output weights is MOST appropriate for the X-Y matrix?",options:["Billing accuracy 1, report timeliness 10","Billing accuracy 10, report timeliness 2","Billing accuracy 9, report timeliness 0","Billing accuracy 3, report timeliness 9"],answer:1,hint:"Weights: 1–10, with 10 = most important.",steps:[{title:"Key idea",body:"Each Y is weighted 1–10 and 10 is most important."},{title:"Apply",body:"The most important Y gets a high weight, the least important a low one within 1–10."}],final:"10 for billing accuracy, low for timeliness → answer **B**",whyWrong:["Incorrect — this reverses the scale: 10 is the most important output.","","Incorrect — 0 is a relationship rating; weights run from 1 to 10.","Incorrect — this also reverses importance and borrows the 0/1/3/9 rating values."],bookRef:"Book p. 120"},{id:"sv-2-682",phase:2,topic:"2.1.3",qtype:"scenario",difficulty:3,stem:"Halfway through Measure, the team adds a new output, *repeat technician visits*, to its X-Y matrix with a high weight. What is the MOST likely effect on the input ranking?",options:["The ranking stays the same because weights only affect outputs","Every input moves down by the same amount","Inputs strongly linked to repeat visits may move up the ranking","The matrix must be discarded and rebuilt from the fishbone"],answer:2,hint:"New Y × its weight is added to every row's total.",steps:[{title:"Key idea",body:"Each new Y adds rating × weight to each X's total."},{title:"Apply",body:"X's rated 9 on the new, heavily weighted Y gain the most and can overtake others."}],final:"Strongly linked inputs rise → answer **C**",whyWrong:["Incorrect — weights multiply ratings, so they change the input totals.","Incorrect — inputs gain according to their rating on the new Y, not equally.","","Incorrect — the matrix is never completed; it is simply updated."],bookRef:"Book pp. 118, 120"},{id:"sv-2-683",phase:2,topic:"2.1.3",qtype:"best-action",difficulty:2,stem:"While weighting the outputs, the team realises that customers strongly value *number of hand-offs*, which is not in the charter. The Black Belt adds it as a secondary metric column and asks the sponsor to update the charter. Was this an appropriate action, and why?",options:["Yes, because new metrics often surface while weighting and may be added as secondary metrics","Yes, because the X-Y matrix replaces the charter once Measure begins","No, because the outputs may only be changed during Define","No, because only the primary metric may appear in the matrix"],answer:0,hint:"Book: new metrics often appear while weighting the Y's.",steps:[{title:"Key idea",body:"The book says new metrics often appear during weighting; you may add secondary metrics or refine the primary metric."},{title:"Apply",body:"Adding the column and updating the charter is the expected response."}],final:"Appropriate — add as a secondary metric → answer **A**",whyWrong:["","Incorrect — the charter remains the agreed project document; the matrix does not replace it.","Incorrect — the book expects new metrics to appear here and allows adding them.","Incorrect — the matrix lists primary and secondary metrics, all customer-focused Y's."],bookRef:"Book p. 120"},{id:"sv-2-684",phase:2,topic:"2.1.3",qtype:"best-action",difficulty:3,stem:"After the output weights are agreed, a process manager pushes to raise one weight so that his preferred input ranks first. What is the BEST action for the Black Belt?",options:["Accept the change because the manager owns the process","Remove all weights and rank the inputs on raw ratings","Delete the inputs that compete with the manager's choice","Base the weight on customer evidence and show the team a sensitivity check"],answer:3,hint:"Weights reflect customer importance; test how much the ranking depends on them.",steps:[{title:"Key idea",body:"Weights come from the customer and business, not from a preferred answer."},{title:"Apply",body:"Re-ranking with the disputed weight shows whether the result is robust."}],final:"Customer-based weight plus sensitivity check → answer **D**",whyWrong:["Incorrect — ownership does not justify biasing the weights.","Incorrect — raw ratings ignore customer importance and weaken the tool.","Incorrect — deleting inputs to suit one person destroys the team-based purpose.",""],bookRef:"Book pp. 118, 120"},{id:"sv-2-685",phase:2,topic:"2.1.3",qtype:"best-action",difficulty:2,stem:"A team is about to score its X-Y matrix for the first time. What is the BEST action to keep the ratings consistent?",options:["Agree what a 9, 3, 1 and 0 mean for this process before scoring","Let each expert score only the rows for their own area","Switch to a 1–100 scale so that ratings are more precise","Score the inputs after looking at last year's ranking"],answer:0,hint:"Shared definitions before scoring.",steps:[{title:"Key idea",body:"Agreeing an operational meaning for each rating keeps the team's judgements consistent."},{title:"Eliminate",body:"Solo scoring, finer scales and anchoring all reduce quality."}],final:"Define the ratings first → answer **A**",whyWrong:["","Incorrect — splitting rows among experts loses the collective judgement.","Incorrect — finer scales invite argument and add no information to opinions.","Incorrect — anchoring on an old ranking biases the new scores."],bookRef:"Book pp. 120–121"},{id:"sv-2-686",phase:2,topic:"2.1.3",qtype:"best-action",difficulty:2,stem:"Using its X-Y matrix, a team has 30 candidate inputs. The Black Belt decides to collect data first on the top five inputs instead of on all 30. Was this an appropriate action, and why?",options:["Yes, because the top five inputs are proven root causes","Yes, because the matrix is used to focus data collection on the inputs believed most influential","No, because data must be collected on every input to avoid bias","No, because data collection should start with the lowest-ranked inputs"],answer:1,hint:"The book puts data work on 'the top X's from the X-Y diagram'.",steps:[{title:"Key idea",body:"The X-Y matrix focuses the team's data collection on the top-ranked X's."},{title:"Apply",body:"The decision is right, but for the focusing reason, not because the X's are proven."}],final:"Appropriate — focus on the top X's → answer **B**",whyWrong:["Incorrect — a high ranking is opinion, not proof of a root cause.","","Incorrect — the matrix exists so the team does not measure every input equally.","Incorrect — the lowest-ranked inputs are the obvious ones to drop."],bookRef:"Book p. 159"},{id:"sv-2-687",phase:2,topic:"2.1.3",qtype:"best-action",difficulty:3,stem:"After the Analyze tests were finished, the Black Belt deleted the X-Y matrix from the project file, saying it was 'done'. Was this an appropriate action, and why?",options:["Yes, because the matrix is only needed until the Analyze tests are finished","Yes, because the Analyze results replace all of the matrix's outputs and weights","No, because it must be signed off by the customer before it can be deleted","No, because it is a living document that is updated and reused later in the project"],answer:3,hint:"'Never completed' — updated whenever a parameter changes.",steps:[{title:"Key idea",body:"The X-Y matrix is a living document, updated whenever a parameter changes."},{title:"Apply",body:"Its Y's and weights are reused in Improve to rank solutions, so it should be kept."}],final:"Not appropriate — the matrix is living → answer **D**",whyWrong:["Incorrect — the book says the matrix is never completed.","Incorrect — the Y's and weights are reused later, for example to rank solutions.","Incorrect — customer sign-off is not a requirement for the matrix.",""],bookRef:"Book p. 118"},{id:"sv-2-688",phase:2,topic:"2.1.3",qtype:"output",difficulty:3,stem:`A network operations team prints its X-Y matrix summary.

\`\`\`
X-Y Matrix — ranking summary
Input                        Ranking   Rank %   Cum %
X3 Ticket triage rules           150     18.0    18.0
X7 Spare-part stock              144     17.3    35.3
X1 Shift handover                138     16.5    51.8
X5 Dispatch rules                132     15.8    67.6
X2 Runbook quality               126     15.1    82.7
X6 Escalation path               120     14.4    97.1
X4 Polling interval               24      2.9   100.0
\`\`\`

Which conclusion is BEST supported by the output?`,options:["Only ticket triage rules should be studied, because it has the highest ranking","There is no sharp break; carry the six higher inputs forward and drop the polling interval","Ticket triage rules is proven to cause most of the restoration delay","The matrix is invalid and must be re-scored until an 80/20 break appears"],answer:1,hint:"Look for a natural gap rather than forcing 80/20.",steps:[{title:"Read",body:"The first six rankings are close together; the polling interval is far lower than the rest."},{title:"Decide",body:"Use judgement: keep the cluster, drop the obvious low-impact X. Opinion totals prove nothing."}],final:"Natural gap: drop only the polling interval → answer **B**",whyWrong:["Incorrect — the top input holds a small share; dropping the others ignores a flat ranking.","","Incorrect — the matrix is opinion; rank % is not proof of causation.","Incorrect — flat X-Y Paretos are common; re-scoring to force a break biases the tool."],bookRef:"Book pp. 118, 122"},{id:"sv-2-689",phase:2,topic:"2.1.3",qtype:"output",difficulty:3,stem:`A field-service team prints its X-Y matrix (Fix = first-time fix) with both unweighted and weighted totals.

\`\`\`
Output (Y)                 Fix  Cost  CSAT
Weight                      10     4     2
Input                                      Unwtd  Weighted
A Route-planning tool        9     0     1      10       92
B Parts on van               1     9     3      13       52
C Job notes quality          3     3     3       9       48
D Customer call-ahead        0     1     9      10       22
\`\`\`

Which statement is supported by the output?`,options:["The unweighted and weighted totals put the inputs in the same order","B should be studied first because it is linked to the most outputs","B has the highest unweighted total, but A ranks first once the weights are applied","D ranks last on both totals because it has the lowest unweighted total"],answer:2,hint:"Read both total columns; the weighted one is the ranking.",steps:[{title:"Read",body:"Unweighted: B is highest. Weighted: A is highest, because its 9 sits under the weight-10 output."},{title:"Decide",body:"Weights change the order; the weighted total is the X-Y ranking."}],final:"Weighting changes the order → answer **C**",whyWrong:["Incorrect — B leads the unweighted column but A leads the weighted column.","Incorrect — the ranking uses weighted totals, where A is first.","","Incorrect — D's unweighted total is not the lowest; C's is."],bookRef:"Book pp. 120–122"},{id:"sv-2-690",phase:2,topic:"2.1.3",qtype:"output",difficulty:1,stem:`The header of a fibre-installation X-Y matrix is shown.

\`\`\`
X-Y Matrix — header
Output (Y)                 Weight
Install right first time       10
Appointment kept                7
Paperwork complete              3

Top-ranked input: Technician skill level (ranking 147)
\`\`\`

Which output does the team consider MOST important?`,options:["Appointment kept","Paperwork complete","Technician skill level","Install right first time"],answer:3,hint:"Importance of a Y = its weight; 10 = most important.",steps:[{title:"Read",body:"Weights: 10, 7 and 3. The highest weight is 10."},{title:"Trap",body:"The top-ranked input is an X; the question asks about the Y's."}],final:"Highest weight = most important Y → answer **D**",whyWrong:["Incorrect — weight 7 is lower than the weight of 10.","Incorrect — weight 3 marks the least important of the three outputs.","Incorrect — this is the top-ranked input (X), not an output (Y).",""],bookRef:"Book p. 120"},{id:"sv-2-691",phase:2,topic:"2.1.3",qtype:"output",difficulty:3,stem:`A service-desk team runs a sensitivity check on its X-Y matrix.

\`\`\`
Sensitivity check — CSAT weight changed from 6 to 10
                           Base weights   CSAT = 10
Input                     Total  Rank    Total  Rank
X1 First-line diagnosis      168    1      172    1
X2 Engineer availability     114    2      114    3
X3 Ticket notes               52    4       64    4
X4 Proactive SMS updates     108    3      144    2
\`\`\`

Which conclusion is correct?`,options:["The order of X2 and X4 depends on the CSAT weight, so that weight should be confirmed","None of the rankings is affected by the change in the CSAT weight","X1's top position depends on the CSAT weight","The change proves that proactive SMS updates cause low CSAT"],answer:0,hint:"Compare the two Rank columns.",steps:[{title:"Read",body:"X1 is first in both columns. X2 and X4 swap positions when CSAT rises to 10."},{title:"Decide",body:"Rankings that hinge on one debatable weight need that weight confirmed with customer evidence."}],final:"X2/X4 order is weight-sensitive → answer **A**",whyWrong:["","Incorrect — X2 and X4 swap rank positions when the weight changes.","Incorrect — X1 ranks first under both sets of weights.","Incorrect — the matrix is opinion; a weight change proves nothing about causes."],bookRef:"Book pp. 118, 120"},{id:"sv-2-692",phase:2,topic:"2.1.3",qtype:"true-false",difficulty:1,stem:"In an X-Y matrix, the inputs (X's) are listed down the left side and the outputs (Y's) across the top.",options:["True","False"],answer:0,hint:"Rows vs columns in the book's template.",steps:[{title:"Key idea",body:"Step 1 lists the X's down the left; step 2 lists the Y's across the top."},{title:"Decide",body:"The statement matches the template."}],final:"True → answer **A**",whyWrong:["","Incorrect — the book's template places the X's in rows and the Y's in columns."],bookRef:"Book p. 120"},{id:"sv-2-693",phase:2,topic:"2.1.3",qtype:"true-false",difficulty:2,stem:"An X-Y matrix is only needed on projects that have no historical data.",options:["True","False"],answer:1,hint:"How often does the book say the matrix is created?",steps:[{title:"Key idea",body:"The book: the X-Y matrix is 'created for every project'."},{title:"Decide",body:"Historical data can feed the X list, but they do not remove the need for the matrix."}],final:"False → answer **B**",whyWrong:["Incorrect — the book says the X-Y matrix is created for every project.",""],bookRef:"Book p. 118"},{id:"sv-2-694",phase:2,topic:"2.1.3",qtype:"true-false",difficulty:1,stem:"In an X-Y matrix, the 1–10 weights are applied to the inputs (X's) rather than to the outputs (Y's).",options:["True","False"],answer:1,hint:"Which side of the matrix carries the importance weights?",steps:[{title:"Key idea",body:"Each Y is weighted 1–10; each X is rated 0/1/3/9 against each Y."},{title:"Decide",body:"The statement swaps the two, so it is false."}],final:"False → answer **B**",whyWrong:["Incorrect — weights describe the importance of each Y; the X's receive 0/1/3/9 ratings.",""],bookRef:"Book p. 120"},{id:"sv-2-695",phase:2,topic:"2.1.3",qtype:"sequence",difficulty:2,stem:`A team has listed its inputs and outputs. In which order should it complete the remaining X-Y matrix steps?

- **P** Score each input against each output
- **Q** Sort the inputs from highest to lowest ranking
- **R** Weight each output from 1 to 10
- **S** Calculate each input's ranking`,options:["P → R → S → Q","R → P → S → Q","R → S → P → Q","P → S → R → Q"],answer:1,hint:"Weights → ratings → totals → sort.",steps:[{title:"Key idea",body:"Book order: list X's, list Y's, weight Y's, score cells, calculate ranking, sort."},{title:"Apply",body:"Weight (R), score (P), calculate (S), sort (Q)."}],final:"R → P → S → Q → answer **B**",whyWrong:["Incorrect — the outputs are weighted before the cells are scored.","","Incorrect — a ranking cannot be calculated before the cells are scored.","Incorrect — the ranking needs the weights, so weighting must come before calculating."],bookRef:"Book pp. 120–121"},{id:"sv-2-696",phase:2,topic:"2.1.3",qtype:"sequence",difficulty:3,stem:`A Black Belt facilitates an X-Y scoring workshop. In which order should these activities take place?

- **P** Rate one output column at a time across all inputs
- **Q** Agree the meaning of the 9, 3, 1 and 0 ratings
- **R** Check how sensitive the ranking is to a debatable weight
- **S** Calculate and sort the totals`,options:["P → Q → S → R","Q → S → P → R","Q → P → S → R","Q → P → R → S"],answer:2,hint:"Define → rate → total → test robustness.",steps:[{title:"Key idea",body:"Agree definitions, rate column by column, compute and sort, then test sensitivity."},{title:"Apply",body:"Q, P, S, R."}],final:"Q → P → S → R → answer **C**",whyWrong:["Incorrect — rating before agreeing what each rating means invites inconsistent scores.","Incorrect — totals cannot be calculated before the cells are rated.","","Incorrect — a sensitivity check needs the totals to exist first."],bookRef:"Book pp. 120–121"},{id:"sv-2-697",phase:2,topic:"2.1.4",qtype:"concept",difficulty:2,stem:"Which is a purpose of an FMEA as described in the book?",options:["To set the specification limits for each customer requirement","To calculate the baseline sigma level of the process","To select the members of the project team","To evaluate the current control plan of the process"],answer:3,hint:"Predict failures, identify how the process fails, estimate S-O-D, evaluate controls, prioritise with RPN.",steps:[{title:"Key idea",body:"The book lists five purposes, including **evaluate the current control plan**."},{title:"Eliminate",body:"Spec limits, sigma level and team selection belong to other tools."}],final:"Evaluate current controls → answer **D**",whyWrong:["Incorrect — specification limits come from the customer (VOC/CTQ), not from the FMEA.","Incorrect — the baseline sigma level comes from capability analysis in Measure.","Incorrect — team selection is part of chartering in Define.",""],bookRef:"Book p. 123"},{id:"sv-2-698",phase:2,topic:"2.1.4",qtype:"concept",difficulty:2,stem:"According to the book, what is the main source for the **potential failure mode** column of a process FMEA?",options:["Capability studies","Historical defect data","MSA studies","Process map"],answer:1,hint:"Failure mode = defect, so where would defects be recorded?",steps:[{title:"Key idea",body:"A failure mode is 'a fancy name for a defect', so it comes from historical defect data."},{title:"Eliminate",body:"Capability → occurrence; MSA → detection; process map → steps and effects."}],final:"Failure modes from defect history → answer **B**",whyWrong:["Incorrect — capability studies inform the occurrence rating.","","Incorrect — MSA studies inform the detection rating.","Incorrect — the process map supplies the steps and the effects."],bookRef:"Book pp. 127–128"},{id:"sv-2-699",phase:2,topic:"2.1.4",qtype:"concept",difficulty:3,stem:"What does the **Class** column of the book's FMEA template record?",options:["Whether the cause is a controllable, procedural or noise input","Whether the failure is critical, major or minor to the customer","Which customer segment is affected by the failure","Which DMAIC phase the recommended action belongs to"],answer:0,hint:"Class reuses the C / P / N labels from the fishbone.",steps:[{title:"Key idea",body:"The Class column marks each cause as C (controllable), P (procedural) or N (noise)."},{title:"Eliminate",body:"Seriousness is severity; segments and phases are not classes."}],final:"Class = C, P or N → answer **A**",whyWrong:["","Incorrect — seriousness for the customer is captured by the severity rating.","Incorrect — affected customers are part of the effect, not the Class column.","Incorrect — actions are recorded with an owner and date, not a phase class."],bookRef:"Book p. 131"},{id:"sv-2-700",phase:2,topic:"2.1.4",qtype:"concept",difficulty:1,stem:"What does RPN stand for in an FMEA?",options:["Rated process nonconformance","Reliability performance number","Risk priority number","Risk probability number"],answer:2,hint:"It tells the team which risks to act on first.",steps:[{title:"Key idea",body:"RPN = risk priority number, used to prioritise actions."},{title:"Trap",body:"It is not a probability: S, O and D are ordinal 1–10 ratings."}],final:"Risk priority number → answer **C**",whyWrong:["Incorrect — not an FMEA term; RPN prioritises risk.","Incorrect — reliability is not what the three ratings combine into.","","Incorrect — RPN is a priority ranking, not a probability."],bookRef:"Book p. 123"},{id:"sv-2-701",phase:2,topic:"2.1.4",qtype:"concept",difficulty:1,stem:"On what scale are the severity, occurrence and detection ratings of an FMEA each scored?",options:["0 to 9","1 to 10","0 to 100","1 to 5"],answer:1,hint:"Each of the three ratings uses the same scale.",steps:[{title:"Key idea",body:"Severity, occurrence and detection are each rated 1–10."},{title:"Trap",body:"Do not mix with the X-Y matrix's 0/1/3/9 ratings."}],final:"Each rating 1–10 → answer **B**",whyWrong:["Incorrect — 0/1/3/9 belongs to the X-Y matrix ratings, not the FMEA.","","Incorrect — 0 to 100 is not used; the RPN itself runs 1 to 1,000.","Incorrect — a 1–5 scale is not the book's FMEA scale."],bookRef:"Book pp. 130–134"},{id:"sv-2-702",phase:2,topic:"2.1.4",qtype:"concept",difficulty:2,stem:"According to the book, what does an FMEA do with the potential X's?",options:["It eliminates them by redesigning the process steps","It proves statistically which of them are significant","It identifies them and the order to evaluate them, rather than eliminating them","It removes any X with an RPN below 100 from the project"],answer:2,hint:"'Not a tool to eliminate X's.'",steps:[{title:"Key idea",body:"The FMEA controls X's: it identifies potential X's and the order in which to evaluate them."},{title:"Eliminate",body:"Elimination, proof and fixed cut-offs are not its role."}],final:"Identifies and prioritises X's → answer **C**",whyWrong:["Incorrect — the book says the FMEA is not a tool to eliminate X's.","Incorrect — statistical proof comes from Analyze-phase tests.","","Incorrect — the book sets no RPN cut-off for removing X's."],bookRef:"Book p. 123"},{id:"sv-2-703",phase:2,topic:"2.1.4",qtype:"concept",difficulty:1,stem:"Who should build a process FMEA?",options:["The quality engineer alone, to keep the ratings consistent","The Champion and the finance partner","A sample of customers who experienced the failures","A cross-functional team of people who define, run or change the process"],answer:3,hint:"FMEA is a team tool built on tribal knowledge.",steps:[{title:"Key idea",body:"The book: the project team plus anyone who defines, runs or changes the process."},{title:"Eliminate",body:"Solo experts, sponsors and customers cannot replace the cross-functional team."}],final:"Cross-functional team → answer **D**",whyWrong:["Incorrect — one person's view loses the team's process knowledge.","Incorrect — sponsors support the project but do not hold the detailed process knowledge.","Incorrect — customer input informs effects, but customers do not build the FMEA.",""],bookRef:"Book p. 125"},{id:"sv-2-704",phase:2,topic:"2.1.4",qtype:"concept",difficulty:2,stem:"In an FMEA, what does the 'recommended actions' column effectively become?",options:["An action plan with owners and dates to reduce the highest risks","A list of the defects found during the baseline period","The operational definitions for each output metric","The specification limits agreed with the customer"],answer:0,hint:"Actions, owner, target date, actions taken.",steps:[{title:"Key idea",body:"Recommended actions, a responsible person and a target date turn the FMEA into an action plan."},{title:"Eliminate",body:"Defect lists, definitions and spec limits belong elsewhere."}],final:"Action plan for top risks → answer **A**",whyWrong:["","Incorrect — past defects are the source of failure modes, not the actions.","Incorrect — operational definitions belong to the data collection plan.","Incorrect — specification limits come from customer requirements."],bookRef:"Book p. 135"},{id:"sv-2-705",phase:2,topic:"2.1.4",qtype:"concept",difficulty:1,stem:"Which statement about the process steps listed in a process FMEA is CORRECT?",options:["They are listed from highest to lowest RPN before scoring","They are listed in the same order as on the process map","They are listed in order of severity before any causes are found","They are listed alphabetically to make the worksheet easier to read"],answer:1,hint:"The first FMEA column is built from the process map.",steps:[{title:"Key idea",body:"The book: steps go in the same order as the process map."},{title:"Eliminate",body:"Ranking by RPN or severity comes later; alphabetical order has no basis."}],final:"Same order as the process map → answer **B**",whyWrong:["Incorrect — RPNs do not exist until the ratings are scored.","","Incorrect — severity is scored after the steps and failure modes are listed.","Incorrect — alphabetical order breaks the link to the process flow."],bookRef:"Book p. 127"},{id:"sv-2-706",phase:2,topic:"2.1.4",qtype:"statements",difficulty:2,stem:`Which statements about the Risk Priority Number (RPN) are CORRECT?

1. It is used to rank failure modes so that actions can be prioritised.
2. It is the product of the severity, occurrence and detection ratings.
3. It is the sum of the severity, occurrence and detection ratings.
4. A higher RPN always means a higher severity rating.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"RPN ranks risks; always look at S, O and D as well.",steps:[{title:"Check each",body:"1 true. 2 true (S × O × D). 3 false (product, not sum). 4 false (any factor can drive it)."},{title:"Match",body:"True pair is 1 and 2."}],final:"Statements 1 and 2 → answer **A**",whyWrong:["","Incorrect — statement 3 is false: the RPN multiplies the three ratings; it does not add them.","Incorrect — both are false: the RPN is a product, and a high RPN can come from O or D alone.","Incorrect — statement 4 is false: a high RPN may be driven by occurrence or detection, not severity."],bookRef:"Book pp. 123, 135"},{id:"sv-2-707",phase:2,topic:"2.1.4",qtype:"statements",difficulty:2,stem:`Which statements correctly match an FMEA column to its main source?

1. Occurrence — capability studies or defect history.
2. Detection — customer satisfaction surveys.
3. Potential causes — the project charter.
4. Process steps — the process map.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:3,hint:"Steps ← process map; causes ← fishbone; occurrence ← capability/history; detection ← MSA.",steps:[{title:"Check each",body:"1 true. 2 false (MSA). 3 false (fishbone). 4 true."},{title:"Match",body:"True pair is 1 and 4."}],final:"Statements 1 and 4 → answer **D**",whyWrong:["Incorrect — statement 2 is false: detection draws on MSA studies and the process map.","Incorrect — both are false: detection uses MSA, and causes come from the fishbone.","Incorrect — statement 3 is false: potential causes come from the fishbone.",""],bookRef:"Book pp. 127–134"},{id:"sv-2-708",phase:2,topic:"2.1.4",qtype:"not-except",difficulty:3,stem:"Which entry would NOT belong in the **potential failure effect** column of a process FMEA?",options:["Customer receives an incorrect bill","Next step receives an incomplete order","Agent selects the wrong tariff code","Service activation is delayed by a day"],answer:2,hint:"Effect = what is felt downstream; mode = how the step fails.",steps:[{title:"Key idea",body:"The effect is the impact on outputs, the next step or the customer."},{title:"Apply",body:"Selecting the wrong code is how the step fails — the failure mode."}],final:"Wrong tariff code is a failure mode → answer **C**",whyWrong:["Incorrect — an incorrect bill is what the customer feels, so it is an effect.","Incorrect — impact on the next step's output is an effect.","","Incorrect — a delayed activation is an impact on the output, so it is an effect."],bookRef:"Book pp. 128–129"},{id:"sv-2-709",phase:2,topic:"2.1.4",qtype:"not-except",difficulty:2,stem:"Which is NOT normally an input used to build a process FMEA in the Measure phase?",options:["The process map","The fishbone diagram","The X-Y matrix","The signed-off final control plan"],answer:3,hint:"Which item is an output at the end of the project, not an input in Measure?",steps:[{title:"Key idea",body:"The book builds the FMEA from the process map, fishbone and X-Y matrix."},{title:"Apply",body:"The final control plan comes later and uses the FMEA, not the other way round."}],final:"Final control plan is not an input → answer **D**",whyWrong:["Incorrect — the process map supplies the steps and effects.","Incorrect — the fishbone supplies the potential causes.","Incorrect — the X-Y matrix's ranked X's feed the potential causes.",""],bookRef:"Book pp. 127, 136"},{id:"sv-2-710",phase:2,topic:"2.1.4",qtype:"not-except",difficulty:3,stem:"Which source would NOT normally be used to rate **occurrence** in an FMEA?",options:["Gage R&R study results","Capability study results","Historical defect records","Cpk of the current process"],answer:0,hint:"Occurrence ← capability and history; detection ← MSA.",steps:[{title:"Key idea",body:"Occurrence uses capability studies, Cpk and defect history."},{title:"Apply",body:"Gage R&R (MSA) informs detection, not occurrence."}],final:"Gage R&R is a detection source → answer **A**",whyWrong:["","Incorrect — capability studies are a named occurrence source.","Incorrect — defect history shows how often the cause has happened.","Incorrect — the AIAG occurrence scale is linked to Cpk values."],bookRef:"Book pp. 132–134"},{id:"sv-2-711",phase:2,topic:"2.1.4",qtype:"scenario",difficulty:1,stem:"A field-service manager wants to know, for each step of the dispatch process, how the step could fail, how serious each failure would be and whether current checks would catch it before the customer notices. Which tool should the Black Belt use?",options:["FMEA","Pareto chart","SIPOC","X-Y matrix"],answer:0,hint:"How it fails + how bad + will we catch it = S, O, D.",steps:[{title:"Key idea",body:"The FMEA rates severity, occurrence and detection for each failure mode."},{title:"Eliminate",body:"Pareto, SIPOC and the X-Y matrix answer different questions."}],final:"FMEA → answer **A**",whyWrong:["","Incorrect — a Pareto chart ranks counted categories, not potential failures.","Incorrect — SIPOC defines high-level scope, not step-level risk.","Incorrect — the X-Y matrix ranks inputs against outputs, not failure risk."],bookRef:"Book p. 123"},{id:"sv-2-712",phase:2,topic:"2.1.4",qtype:"true-false",difficulty:1,stem:"In a process FMEA, the potential causes column is usually completed using the fishbone diagram.",options:["True","False"],answer:0,hint:"Which tool brainstorms causes?",steps:[{title:"Key idea",body:"Potential causes (X's) come from the fishbone."},{title:"Decide",body:"The statement is true."}],final:"True → answer **A**",whyWrong:["","Incorrect — the book names the fishbone as the source of potential causes."],bookRef:"Book p. 131"},{id:"sv-2-713",phase:2,topic:"2.1.4",qtype:"true-false",difficulty:2,stem:"An FMEA is mainly a problem-solving tool that is used after a defect has reached the customer.",options:["True","False"],answer:1,hint:"Prevention or cure?",steps:[{title:"Key idea",body:"The book: FMEAs focus on continuous problem prevention, not problem solving."},{title:"Decide",body:"It predicts failures before they reach the customer, so the statement is false."}],final:"False → answer **B**",whyWrong:["Incorrect — the book says FMEAs focus on continuous problem prevention, not problem solving.",""],bookRef:"Book p. 125"},{id:"sv-2-714",phase:2,topic:"2.1.4",qtype:"sequence",difficulty:2,stem:`Arrange these AIAG severity descriptions from the LOWEST rating to the HIGHEST.

- **P** Hazardous without warning
- **Q** No effect
- **R** Loss of primary function, very dissatisfied customer
- **S** Reduced performance, some dissatisfaction`,options:["Q → R → S → P","Q → S → R → P","S → Q → R → P","Q → S → P → R"],answer:1,hint:"1 = no effect … 10 = hazardous without warning.",steps:[{title:"Key idea",body:"AIAG: 1 no effect, about 5 reduced performance, 8 loss of primary function, 10 hazardous without warning."},{title:"Apply",body:"Q, S, R, P."}],final:"Q → S → R → P → answer **B**",whyWrong:["Incorrect — loss of primary function (about 8) is more severe than reduced performance (about 5).","","Incorrect — 'no effect' is severity 1, the lowest.","Incorrect — hazardous without warning is 10, the highest."],bookRef:"Book p. 130"},{id:"sv-2-715",phase:2,topic:"2.1.4",qtype:"output",difficulty:2,stem:`An order-entry FMEA extract is shown.

\`\`\`
Process FMEA — order entry
Failure mode                    SEV  OCC  DET   RPN
Wrong tariff selected             6    6    4   144
Credit check skipped              7    2    9   126
Duplicate order created           4    7    2    56
Address not validated             8    3    1    24
\`\`\`

For which failure mode are the current controls LEAST likely to catch the failure?`,options:["Wrong tariff selected","Duplicate order created","Credit check skipped","Address not validated"],answer:2,hint:"Read the DET column; high = poor detection.",steps:[{title:"Read",body:"DET values: 4, 9, 2 and 1. The highest is 9 for 'Credit check skipped'."},{title:"Trap",body:"Do not pick the highest RPN or read DET = 1 as poor."}],final:"Highest DET = weakest control → answer **C**",whyWrong:["Incorrect — this has the highest RPN, but its detection rating is not the worst.","Incorrect — this has the highest occurrence, not the poorest detection.","","Incorrect — DET = 1 means detection is almost certain; that is the best control."],bookRef:"Book pp. 133–134"},{id:"sv-2-716",phase:2,topic:"2.1.4",qtype:"concept",difficulty:1,stem:"In an FMEA, what does the **potential cause** column describe?",options:["How the process step fails — the defect itself","What the next step or customer experiences","What currently prevents or detects the failure","How the failure could occur — the X behind it"],answer:3,hint:"Cause = why; mode = how it fails; effect = so what; control = what stops it.",steps:[{title:"Key idea",body:"The potential cause is the X that makes the failure happen; it comes mainly from the fishbone."},{title:"Eliminate",body:"Mode, effect and control are neighbouring columns with different jobs."}],final:"Cause = the X → answer **D**",whyWrong:["Incorrect — this is the potential failure mode.","Incorrect — this is the potential failure effect.","Incorrect — this is the current process controls column.",""],bookRef:"Book p. 131"},{id:"sv-2-717",phase:2,topic:"2.1.4",qtype:"concept",difficulty:2,stem:"According to the book's definition, an FMEA identifies the ways a process can fail to meet what?",options:["Critical customer requirements (the Y's)","Internal efficiency targets set by finance","The resolution required of the measurement system","The financial benefit estimate in the charter"],answer:0,hint:"Failure is defined against what the customer needs.",steps:[{title:"Key idea",body:"The book: FMEA identifies the ways a process can fail to meet critical customer requirements (Y)."},{title:"Eliminate",body:"Finance targets, MSA resolution and charter benefits are not the reference."}],final:"Critical customer requirements → answer **A**",whyWrong:["","Incorrect — the book ties failure to customer requirements, not internal finance targets.","Incorrect — measurement resolution is an MSA topic.","Incorrect — the benefit estimate is a charter item, not what a process fails to meet."],bookRef:"Book p. 123"},{id:"sv-2-718",phase:2,topic:"2.1.4",qtype:"concept",difficulty:2,stem:"On the AIAG occurrence scale used in the book, what does an occurrence rating of **10** indicate?",options:["The cause is remote, around 1 in 1,500,000 or fewer","The cause is almost inevitable, around 1 in 2 or more","The failure is almost impossible to detect","The effect is hazardous without warning"],answer:1,hint:"Every FMEA scale: 10 is the worst end of that scale.",steps:[{title:"Key idea",body:"AIAG occurrence: 10 ≈ 1 in 2 or more (Cpk below 0.33); 1 ≈ 1 in 1,500,000 or fewer."},{title:"Eliminate",body:"Detection 10 and severity 10 describe other scales."}],final:"Occurrence 10 = almost inevitable → answer **B**",whyWrong:["Incorrect — this describes an occurrence rating of 1.","","Incorrect — this is a detection rating of 10.","Incorrect — this is a severity rating of 10."],bookRef:"Book p. 132"},{id:"sv-2-719",phase:2,topic:"2.1.4",qtype:"concept",difficulty:2,stem:"How does an FMEA differ from a fishbone diagram?",options:["It lists possible causes by category without rating them","It ranks inputs by their impact on weighted outputs","It rates the risk of each failure and cause rather than only listing possible causes","It shows the process steps and decisions in sequence"],answer:2,hint:"The fishbone feeds the FMEA's cause column; the FMEA adds S, O and D.",steps:[{title:"Key idea",body:"The fishbone brainstorms causes; the FMEA rates severity, occurrence and detection to rank risk."},{title:"Eliminate",body:"Weighted-output ranking is the X-Y matrix; step sequences are process maps."}],final:"FMEA rates risk; fishbone lists causes → answer **C**",whyWrong:["Incorrect — listing causes by category without ratings is the fishbone itself.","Incorrect — ranking inputs against weighted outputs is the X-Y matrix.","","Incorrect — steps and decisions in sequence form a process map."],bookRef:"Book pp. 123, 131"},{id:"sv-2-720",phase:2,topic:"2.1.4",qtype:"concept",difficulty:1,stem:"What does a high RPN tell an FMEA team?",options:["That the failure has already reached the customer","That the cause has been proven with data","That the severity rating must be 10","That the failure mode and cause should be considered early for action"],answer:3,hint:"RPN = a priority ranking for action.",steps:[{title:"Key idea",body:"The RPN ranks failure modes so the team acts on the highest risks first."},{title:"Eliminate",body:"It is not an escape report, a proof or a severity reading."}],final:"High RPN = act early → answer **D**",whyWrong:["Incorrect — the FMEA predicts potential failures; it does not report escapes.","Incorrect — ratings start as team judgement; proof needs data.","Incorrect — a high RPN can come from occurrence or detection, not only severity.",""],bookRef:"Book pp. 123, 135"},{id:"sv-2-721",phase:2,topic:"2.1.4",qtype:"concept",difficulty:2,stem:"Which statement about the potential failure effect in an FMEA is CORRECT?",options:["It describes the impact of the failure on the step's outputs, the Y's or the customer","It describes how the process step fails to do its job","It is rated for occurrence rather than for severity","It is taken mainly from measurement system studies"],answer:0,hint:"Effect = 'so what?' — and it is what severity rates.",steps:[{title:"Key idea",body:"The effect is the impact on outputs or the customer; severity rates it; the process map is its source."},{title:"Eliminate",body:"Mode is how it fails; occurrence rates causes; MSA supports detection."}],final:"Effect = impact on outputs or customer → answer **A**",whyWrong:["","Incorrect — how the step fails is the failure mode.","Incorrect — the effect carries the severity rating; occurrence belongs to the cause.","Incorrect — MSA studies inform detection; effects come from the process map and VOC."],bookRef:"Book pp. 128–130"},{id:"sv-2-722",phase:2,topic:"2.1.4",qtype:"concept",difficulty:3,stem:"Which statement about rating detection when a cause has **no current control** is CORRECT?",options:["Detection should be rated 1, because no control means no false alarms","Detection should be rated at or near 10, because nothing would catch the failure","Detection should be left blank until a control is installed","Detection should copy the occurrence rating for that cause"],answer:1,hint:"No control = almost impossible to detect.",steps:[{title:"Key idea",body:"Detection 10 = almost impossible to detect, which includes having no control at all."},{title:"Eliminate",body:"A low score, a blank or a copied value would understate the risk."}],final:"No control → detection near 10 → answer **B**",whyWrong:["Incorrect — 1 means almost certain detection, the opposite of having no control.","","Incorrect — every row is rated so the RPN can rank it; a blank hides the risk.","Incorrect — detection and occurrence are separate judgements."],bookRef:"Book pp. 133–134"},{id:"sv-2-723",phase:2,topic:"2.1.4",qtype:"concept",difficulty:2,stem:"Which statement about the FMEA and the control plan is CORRECT?",options:["The control plan is written first and the FMEA is copied from it","The FMEA is discarded once a control plan exists","The FMEA identifies and ranks risks; the control plan documents how key X's are monitored","Both documents rank inputs by weighted customer importance"],answer:2,hint:"FMEA = where is the risk; control plan = how we keep it controlled.",steps:[{title:"Key idea",body:"The book uses the updated FMEA as a source for the Control-phase monitoring and response plan."},{title:"Eliminate",body:"It is not copied from, replaced by or the same as the control plan."}],final:"FMEA ranks risk; control plan monitors X's → answer **C**",whyWrong:["Incorrect — the FMEA comes first and feeds the control plan.","Incorrect — the FMEA is a living document kept up to date.","","Incorrect — weighted customer importance is the X-Y matrix approach."],bookRef:"Book pp. 135, 570"},{id:"sv-2-724",phase:2,topic:"2.1.4",qtype:"statements",difficulty:2,stem:`Which statements reflect the book's definition of an FMEA?

1. It is mainly used to solve problems after customer complaints.
2. It predicts failures and helps prevent their occurrence.
3. It estimates the severity, occurrence and detection of defects.
4. It eliminates potential X's from the process.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"Predict, prevent, estimate SOD, evaluate controls, prioritise.",steps:[{title:"Check each",body:"1 false (prevention). 2 true. 3 true. 4 false (controls, not eliminates)."},{title:"Match",body:"True pair is 2 and 3."}],final:"Statements 2 and 3 → answer **B**",whyWrong:["Incorrect — statement 1 is false: FMEA focuses on prevention, not problem solving.","","Incorrect — statement 4 is false: the FMEA is not a tool to eliminate X's.","Incorrect — both are false: it prevents rather than solves, and it does not eliminate X's."],bookRef:"Book pp. 123, 125"},{id:"sv-2-725",phase:2,topic:"2.1.4",qtype:"statements",difficulty:3,stem:`A team is entering the step *post customer payment* into its FMEA. Which entries belong in the **potential cause** column?

1. Payment posted to the wrong account.
2. Customer receives an incorrect overdue notice.
3. Similar account numbers are shown side by side on screen.
4. Agent works from an outdated account reference list.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"Cause = why the step could fail.",steps:[{title:"Classify",body:"1 = failure mode (how it fails). 2 = effect (what the customer feels). 3 and 4 = reasons it could happen."},{title:"Match",body:"Causes are 3 and 4."}],final:"Statements 3 and 4 → answer **C**",whyWrong:["Incorrect — 1 is the failure mode and 2 is the effect.","Incorrect — 2 is the effect felt by the customer, not a cause.","","Incorrect — 1 describes how the step fails (the failure mode), not why."],bookRef:"Book pp. 128–131"},{id:"sv-2-726",phase:2,topic:"2.1.4",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

An FMEA is a structured approach to predict failures and [?] their occurrence.`,options:["detect","measure","prevent","record"],answer:2,hint:"FMEA focuses on problem prevention.",steps:[{title:"Key idea",body:"The book's first purpose: predict failures and prevent their occurrence."},{title:"Eliminate",body:"Detecting, measuring and recording are not the stated aim."}],final:"Prevent → answer **C**",whyWrong:["Incorrect — detection is one rating, not the aim stated in the definition.","Incorrect — measuring belongs to MSA and capability work.","","Incorrect — recording failures is reactive; the FMEA is preventive."],bookRef:"Book p. 123"},{id:"sv-2-727",phase:2,topic:"2.1.4",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

An FMEA estimates the severity, occurrence and [?] (SOD) of defects.`,options:["demand","detection","distribution","duration"],answer:1,hint:"S-O-D.",steps:[{title:"Key idea",body:"SOD = severity, occurrence and detection, the three 1–10 ratings."},{title:"Apply",body:"The third rating is detection."}],final:"Detection → answer **B**",whyWrong:["Incorrect — customer demand is not one of the FMEA ratings.","","Incorrect — distribution describes data shape, not an FMEA rating.","Incorrect — duration is not one of the three ratings."],bookRef:"Book p. 123"},{id:"sv-2-728",phase:2,topic:"2.1.4",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

The Risk Priority Number is used to [?] actions in an FMEA.`,options:["approve","fund","prioritise","schedule"],answer:2,hint:"The name says it: risk PRIORITY number.",steps:[{title:"Key idea",body:"The book: prioritise actions using the Risk Priority Number."},{title:"Eliminate",body:"Approval, funding and scheduling are separate decisions."}],final:"Prioritise → answer **C**",whyWrong:["Incorrect — approval is a management decision, not the RPN's role.","Incorrect — funding is not what the RPN is defined to do.","","Incorrect — target dates are set by the team, not by the RPN."],bookRef:"Book p. 123"},{id:"sv-2-729",phase:2,topic:"2.1.4",qtype:"not-except",difficulty:2,stem:"All of the following are normally recorded for each recommended action in an FMEA EXCEPT:",options:["The person responsible for the action","The target completion date","The action taken and its effective date","The p-value of the cause from an Analyze test"],answer:3,hint:"Recommended action → owner → target date → actions taken → new ratings.",steps:[{title:"Key idea",body:"The book's template records the action, responsible person, target date and actions taken."},{title:"Apply",body:"p-values belong to Analyze test outputs, not the FMEA action columns."}],final:"p-value is not an action column → answer **D**",whyWrong:["Incorrect — a named owner is part of the action columns.","Incorrect — a target date is part of the action columns.","Incorrect — the actions-taken column records what was done and when.",""],bookRef:"Book pp. 127–135"},{id:"sv-2-730",phase:2,topic:"2.1.4",qtype:"scenario",difficulty:2,stem:"In a billing FMEA, the team notes that a *nightly reconciliation report* flags payments posted to the wrong account. In which column should this report be recorded?",options:["Current process controls","Potential cause","Potential failure effect","Potential failure mode"],answer:0,hint:"Something that catches the failure = a control.",steps:[{title:"Key idea",body:"Current controls are what prevent or detect the failure today; they set the detection rating."},{title:"Apply",body:"A report that flags wrong postings is a detection control."}],final:"Current process controls → answer **A**",whyWrong:["","Incorrect — a cause explains why the failure happens; the report does not cause it.","Incorrect — an effect is what the customer or next step experiences.","Incorrect — the failure mode is the wrong posting itself."],bookRef:"Book p. 133"},{id:"sv-2-731",phase:2,topic:"2.1.4",qtype:"scenario",difficulty:2,stem:"For the step *activate SIM*, a team writes the failure mode *customer is unhappy with the delay*. What is wrong with this entry?",options:["It is an effect of the failure, not the way the step fails","It is a current control, not a failure mode","It is a potential cause, not a failure mode","Nothing — customer feelings are the best failure modes"],answer:0,hint:"Mode = the defect at the step; effect = the consequence.",steps:[{title:"Key idea",body:"A failure mode is how the step fails (e.g. SIM not activated within target); the effect is what the customer feels."},{title:"Apply",body:"'Customer is unhappy' is a consequence, so it belongs in the effect column."}],final:"It is an effect → answer **A**",whyWrong:["","Incorrect — a control prevents or detects failures; unhappiness does neither.","Incorrect — a cause explains why the step fails; unhappiness is a consequence.","Incorrect — failure modes describe how the step fails, essentially the defect."],bookRef:"Book pp. 128–129"},{id:"sv-2-732",phase:2,topic:"2.1.4",qtype:"scenario",difficulty:3,stem:"A failure mode in a broadband FMEA is rated **S = 7, O = 2, D = 9**. What do these ratings tell the team?",options:["The failure is frequent and easy to detect, so prevention is the priority","The failure is rare but would usually escape, so better detection would cut the risk most","The failure is minor, so it can be removed from the FMEA","The failure is hazardous, so severity must be lowered first"],answer:1,hint:"Read each factor, not just the product.",steps:[{title:"Read",body:"O = 2: the cause is rare. D = 9: the control would usually miss it. S = 7: a serious effect."},{title:"Decide",body:"The detection rating is the weak point, so improving the control gives the biggest gain."}],final:"Detection is the weak point → answer **B**",whyWrong:["Incorrect — O = 2 means rare and D = 9 means hard to detect.","","Incorrect — S = 7 is a significant effect, and failure modes are not deleted for being minor.","Incorrect — 7 is not in the hazardous band, and severity rarely changes without redesign."],bookRef:"Book pp. 132–135"},{id:"sv-2-733",phase:2,topic:"2.1.4",qtype:"scenario",difficulty:2,stem:"Before Control, a team must choose which inputs to monitor. It wants those whose failure would be most serious, most frequent and least likely to be caught. Which tool's output should it use?",options:["FMEA","Pareto chart","SIPOC","X-Y matrix"],answer:0,hint:"Serious + frequent + hard to catch = S, O, D.",steps:[{title:"Key idea",body:"The FMEA's RPN combines severity, occurrence and detection, and the book uses it for the monitoring plan."},{title:"Eliminate",body:"Pareto, SIPOC and the X-Y matrix do not rate all three."}],final:"FMEA → answer **A**",whyWrong:["","Incorrect — a Pareto chart ranks counted categories, not severity and detection.","Incorrect — SIPOC defines high-level scope only.","Incorrect — the X-Y matrix ranks believed impact on outputs, without severity or detection."],bookRef:"Book pp. 135, 570"},{id:"sv-2-734",phase:2,topic:"2.1.4",qtype:"best-action",difficulty:3,stem:"After the fishbone session, the Black Belt puts the controllable X's into the X-Y matrix and carries the procedural and noise X's into the FMEA. Was this an appropriate action, and why?",options:["Yes, because the book sends procedural and noise X's to the FMEA","Yes, because procedural and noise X's always have the highest RPNs","No, because only controllable X's may appear in an FMEA","No, because noise X's cannot be rated, so they are left out"],answer:0,hint:"Controllable → X-Y matrix; procedural and noise → FMEA.",steps:[{title:"Key idea",body:"The book places controllable X's in the X-Y matrix and procedural and noise X's in the FMEA."},{title:"Apply",body:"The action follows the book for the right reason."}],final:"Appropriate → answer **A**",whyWrong:["","Incorrect — no class of X automatically has the highest RPN.","Incorrect — the FMEA's Class column includes P and N inputs.","Incorrect — noise X's are kept because they tend to raise risk."],bookRef:"Book p. 119"},{id:"sv-2-735",phase:2,topic:"2.1.4",qtype:"best-action",difficulty:2,stem:"Several high-RPN causes in an FMEA have no current control. What is the BEST next action?",options:["Lower their detection ratings because controls are being planned","Delete those rows until controls have been installed","Assign recommended actions with an owner and target date for those causes","Raise their severity ratings so they rank even higher"],answer:2,hint:"High RPN → recommended action, owner, date.",steps:[{title:"Key idea",body:"The FMEA evaluates the control plan and prioritises actions on the highest RPNs."},{title:"Apply",body:"Uncontrolled high-risk causes need owned, dated actions."}],final:"Assign owned, dated actions → answer **C**",whyWrong:["Incorrect — ratings are re-scored only after actions are taken.","Incorrect — deleting rows hides the very risks the FMEA should manage.","","Incorrect — severity rates the effect and does not change to reflect missing controls."],bookRef:"Book p. 135"},{id:"sv-2-736",phase:2,topic:"2.1.4",qtype:"best-action",difficulty:2,stem:"To save time, a Black Belt ranks the failure modes by **adding** severity, occurrence and detection instead of multiplying them. Was this an appropriate action, and why?",options:["Yes, because adding and multiplying always give the same ranking","Yes, because the book allows any method of combining the ratings","No, because the RPN is defined as the product of S, O and D","No, because only severity should be used to rank failure modes"],answer:2,hint:"RPN = S × O × D.",steps:[{title:"Key idea",body:"The book defines the RPN as severity × occurrence × detection."},{title:"Apply",body:"A sum is not the RPN, so the ranking may differ from the agreed method."}],final:"Not appropriate — RPN is a product → answer **C**",whyWrong:["Incorrect — sums and products can rank failure modes differently.","Incorrect — the book defines the RPN as S × O × D.","","Incorrect — the RPN uses all three ratings; severity alone is not the ranking rule."],bookRef:"Book p. 135"},{id:"sv-2-737",phase:2,topic:"2.1.4",qtype:"sequence",difficulty:2,stem:`On the AIAG occurrence scale, arrange these process capabilities from the HIGHEST occurrence rating to the LOWEST.

- **P** Cpk ≥ 1.67
- **Q** Cpk < 0.33
- **R** Cpk ≥ 1.33
- **S** Cpk ≥ 1.00`,options:["P → R → S → Q","Q → R → S → P","S → Q → R → P","Q → S → R → P"],answer:3,hint:"Lower capability → more frequent failures → higher occurrence.",steps:[{title:"Key idea",body:"AIAG: Cpk < 0.33 → 10; ≥ 1.00 → 5; ≥ 1.33 → 3; ≥ 1.67 → 1."},{title:"Apply",body:"Q, S, R, P."}],final:"Q → S → R → P → answer **D**",whyWrong:["Incorrect — this is the reverse: high Cpk means rare causes and a low rating.","Incorrect — Cpk ≥ 1.00 (rating 5) ranks above Cpk ≥ 1.33 (rating 3).","Incorrect — Cpk < 0.33 is the worst capability, so it has the highest rating.",""],bookRef:"Book p. 132"},{id:"sv-2-738",phase:2,topic:"2.1.4",qtype:"sequence",difficulty:1,stem:`Arrange these detection descriptions from the LOWEST detection rating to the HIGHEST.

- **P** Moderate
- **Q** Almost impossible
- **R** Almost certain
- **S** High`,options:["R → S → P → Q","Q → P → S → R","R → P → S → Q","S → R → P → Q"],answer:0,hint:"Detection is inverted: better detection = lower number.",steps:[{title:"Key idea",body:"Book scale: 1 almost certain, 3 high, 5 moderate, 10 almost impossible."},{title:"Apply",body:"R, S, P, Q."}],final:"R → S → P → Q → answer **A**",whyWrong:["","Incorrect — this is the reverse: 'almost certain' detection earns the lowest number.","Incorrect — 'high' detection (about 3) is rated below 'moderate' (about 5).","Incorrect — 'almost certain' (1) is rated below 'high' (3)."],bookRef:"Book p. 134"},{id:"sv-2-739",phase:2,topic:"2.1.4",qtype:"output",difficulty:2,stem:`An online-sales FMEA extract is shown.

\`\`\`
Process FMEA — online sales
Failure mode                    SEV  OCC  DET   RPN
Promo code not applied            3    8    2    48
Contract not signed               8    4    6   192
Wrong handset shipped             7    3    7   147
Delivery slot missed              6    5    5   150
\`\`\`

Which statement is supported by the output?`,options:["The failure with the highest occurrence also has the highest RPN","The failure with the highest occurrence has the lowest RPN, because its severity and detection are low","'Wrong handset shipped' has the poorest detection and the highest RPN","'Delivery slot missed' has the highest severity on the worksheet"],answer:1,hint:"Read each column separately before comparing RPNs.",steps:[{title:"Read",body:"Highest OCC = 8 (promo code), yet its RPN is the lowest because SEV = 3 and DET = 2."},{title:"Decide",body:"A single high rating does not make the highest risk; the RPN combines all three."}],final:"High OCC alone ≠ highest risk → answer **B**",whyWrong:["Incorrect — 'Promo code not applied' has the highest OCC but the lowest RPN.","","Incorrect — its DET is the highest, but 'Contract not signed' has the higher RPN.","Incorrect — the highest SEV belongs to 'Contract not signed'."],bookRef:"Book p. 135"},{id:"sv-2-740",phase:2,topic:"2.1.4",qtype:"output",difficulty:3,stem:`An FMEA extract is shown.

\`\`\`
Process FMEA — tariff selection (extract)
Failure mode            Cause                          Class SEV OCC DET  RPN
Wrong tariff selected   Similar tariff names in menu     C    6   5   4  120
Wrong tariff selected   Agent skips tariff checklist     P    6   6   5  180
Wrong tariff selected   Peak-hour call volume surges     N    6   4   6  144
\`\`\`

Which cause is MOST directly addressed by enforcing standard procedures and training on them?`,options:["Similar tariff names in menu","Peak-hour call volume surges","Agent skips tariff checklist","All three causes equally"],answer:2,hint:"Class P = procedural input.",steps:[{title:"Read",body:"Class column: C for menu names, P for the skipped checklist, N for call surges."},{title:"Decide",body:"Procedural (P) inputs are addressed by procedures and compliance."}],final:"The P-class cause → answer **C**",whyWrong:["Incorrect — class C: a controllable design of the menu, fixed by changing it (e.g. mistake proofing).","Incorrect — class N: noise the team cannot or will not control.","","Incorrect — the Class column shows they are different kinds of input."],bookRef:"Book pp. 119, 131"}];export{e as items};
